/* AIDM B1 S17 Giant Rat — source-checked seed, 2026-11-22; rerunnable, preserve existing records. */
USE [DnD];
GO
IF OBJECT_ID(N'Rules.Monster',N'U') IS NULL OR COL_LENGTH(N'Rules.Monster',N'SpecialAttacksFeatures') IS NULL OR COL_LENGTH(N'Rules.Monster',N'SpecialEncounterFeatures') IS NULL OR COL_LENGTH(N'Rules.Monster',N'D1Feet') IS NULL THROW 57017,'Rules.Monster v0.4 required',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 IF NOT EXISTS(SELECT 1 FROM [Rules].[Monster] WITH(UPDLOCK,HOLDLOCK) WHERE [RulesetCode]=N'MentzerBECMI' AND [MonsterCode]=N'GIANT_RAT')
 BEGIN
  INSERT INTO [Rules].[Monster] ([RecordDate],[RulesetCode],[MonsterCode],[Active],[MonsterName],[ParentMonsterCode],[SourceStatus],[SourceReference],[HouseRuleOverlayRefs],[ArmorClass],[HitDiceText],[AttackPattern],[DamagePattern],[SaveAs],[Morale],[MovementTurnFeet],[MovementRoundFeet],[MovementSpecialText],[Alignment],[XPValue],[NumberAppearingText],[TreasureType],[GeneralDescription],[SpecialAttacksFeatures],[SpecialEncounterFeatures],[D1Feet],[D2Feet],[ZFeet],[SizeBasis],[IllustrationPath],[MapIconPath],[NotesMarkdown])
  VALUES (CONVERT(DATE,SYSUTCDATETIME()),N'MentzerBECMI',N'GIANT_RAT',0,N'Giant Rat',NULL,N'SourceChecked',N'Mentzer Basic (1983) Dungeon Masters Rulebook, Rat (Normal and Giant), printed p.36; B1 In Search of the Unknown stocklist #17 selects species only; encounter values newly generated for S17.',NULL,7,N'1/2 (1d4 HP)',N'1 bite per Giant Rat',N'1d3 physical damage + chance of disease after successful bite',N'Normal Man',8,120,40,N'Swimming 60 feet per turn, 20 feet per round',N'Neutral',NULL,N'3-18 (3-30)',N'C',N'A Giant Rat is a black- or gray-furred dungeon rodent at least three feet long, with sharp teeth and a naked tail. These eight rats inhabit a shallow flooded, torchlit stone corridor. Their approved original stock illustration is presentation-only. Proposed AIDM model dimensions 3.5ft long, 1.5ft broad and 1.5ft high are estimates, NOT published Mentzer measurements.',N'GIANT RAT COMBAT — Mentzer Basic 1983. AC 7; Hit Dice 1/2, 1d4 HP each; Save As Normal Man, Morale 8. Each Giant Rat makes ONE independent bite attack using its applicable monster attack row; on a successful hit deal 1d3 normal hit-point DAMAGE. A miss inflicts no damage and causes no disease check. DISEASE PROCEDURE: AFTER EACH successful rat bite, independently roll 1d20; on exactly 1 (one in twenty) the bitten character is exposed and must make a normal Saving Throw vs Poison using their authoritative save profile. No saving throw if the 1d20 disease check did not trigger. On a successful Save vs Poison, no disease condition. On a failed Save vs Poison, request a transition to named state DISEASED for the ACTUAL bitten target; capture source rat/attack/event ID. Combat ends its disease-specific processing at that state assignment: no second instant HP damage, premature death, bedridden penalty, world-clock advancement or recovery. Reusable State Engine story AIDM-DES-017.3 manages DISEASED registration; future disease lifecycle is separate. Giant Rats attack individually; do NOT use normal-rat pack attack or any invented multiattack. Rats can attack while swimming, movement swim 60ft/turn (20ft/round); no innate to-Hit or damage modifier for swimming. Fear of fire is a behavioural Encounter rule, NOT a numerical combat penalty or magical Fear status.',N'GIANT RAT ENCOUNTER — Mentzer Basic. Number Appearing 3-18 ordinarily (3-30 parenthetical): source gives range; this ONE synthetic test uses 3d6 [3,3,2] = eight. Giant Rats are at least 3ft long, with gray or black fur, favor dank dungeon locations and may live near undead. Rats ordinarily avoid people, fighting when defending a lair, cornered or compelled by a summoner (e.g. wererat); they generally flee from fire unless compelled to fight. Swimmers: 60ft/turn, 20ft/round; walking 120ft/turn, 40ft/round. Giant Rats attack as individual actors, not as the separate normal-rat pack attack. Normal surprise rolls 1d6 once per side, surprised on 1-2; no innate surprise bonus. Set positions, visibility, fire and escape routes explicitly in Encounter/Geometry. For S17 single ordinary flooded dungeon passage, eight rats are cornered; surprise party 5, rats 2. Do not force attack solely due to illustration; DM interprets player and rat intent.',3.5,1.5,1.5,N'AIDM approximate 3.5ft length x 1.5ft width x 1.5ft height; Mentzer gives only at least 3ft length.',N'assets/monsters/AIDM_GIANT_RAT_S17_Dungeon_Stock_Illustration.webp',NULL,N'S17 RAT-T001: one non-lair giant-rat dungeon encounter with eight individuals, 16 specified tests (12 Combat and 4 Encounter). XP field deliberately NULL because printed rat XP value was not confirmed during source review. Proposed size dimensions are estimates, not owner-approved published statistics. No SQL run or UAT asserted.');
  PRINT N'Inserted inactive Giant Rat species';
 END ELSE PRINT N'Existing Giant Rat species preserved';
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [MonsterCode],[SourceStatus],[Active],[ArmorClass],[HitDiceText],[Morale],[D1Feet],[D2Feet],[ZFeet],[IllustrationPath],LEN([SpecialAttacksFeatures]) AS [CombatFeatureChars] FROM [Rules].[Monster] WHERE [RulesetCode]=N'MentzerBECMI' AND [MonsterCode]=N'GIANT_RAT';
GO
